"""Generate public diligence from current investor documents; no historical model overwrite."""
from pathlib import Path
import json,html,re
p=Path(__file__).resolve().parents[1];repo=p.parents[1];docs=repo/'docs/investor';h=html.escape
model=json.loads((docs/'financial-model.json').read_text());legacy=json.loads((p/'finance/assumptions.json').read_text());(p/'assets/assumptions.json').write_text(json.dumps(legacy,indent=2)+'\n')
sections=[]
def sec(id,title,body):sections.append((id,title,f'<section id="{id}"><h2>{h(title)}</h2>{body}</section>'))
def paras(text):return ''.join('<p>'+h(x)+'</p>' for x in text.split('\n\n'))
sec('architecture','Language, execution, evidence and assurance',paras('Kujo compiles and executes programs. Spec describes task contracts. PackWrite compiles execution packs. Dispatch orchestrates workflow state. Workcell documents bounded execution. CaseFile captures command output; RunLedger stores supplied run receipts and Git facts. Eval evaluates configured checks; ShipCheck reports release-readiness signals. These components have distinct contracts; no universal enforcement is implied.\n\nThe proposed paid service adds shared evidence intake, retention, access control, review and export. Hosted custody, tenant isolation, support and customer validation remain planned work.'))
caps=json.loads((p/'research/capabilities.json').read_text());sec('maturity','Available tooling and scope','<ul>'+''.join(f'<li><a href="{h(c["source"])}">{h(c["project"])}</a>: {h(c["capability"])}. {h(c["status"])}. {h(c["limitations"])}</li>' for c in caps)+'</ul><p>Command Code, Hermes, OpenCode and Pi adapters are documented in pinned public repositories. Their version-specific tests are not a blanket certification. No hosted paid SKU or active pilot was verified.</p>')
e=p/'assets/checkout-evidence';files=sorted(x for x in e.rglob('*') if x.is_file());before=next(x for x in files if x.name=='case.json' and 'before' in str(x));after=next(x for x in files if x.name=='case.json' and 'after' in str(x))
buttons=''.join(f'<button data-evidence="{k}">{v}</button>' for k,v in [('request','Task'),('diff','Correction'),('before','Failed command'),('after','Passed command'),('eval','Evaluation'),('decision','Review')])
sec('evidence','A coupon must preserve free shipping','<p><strong>Controlled local checkout fixture, rerun for this briefing.</strong> A $50 cart with a 10% coupon incorrectly totals $50.99. One of three Python tests fails. The driver changes shipping eligibility to use the original subtotal; all three unchanged tests then pass. This is a deterministic correction, not an autonomous model repair or customer incident.</p><div class="evidence-nav">'+buttons+'</div><pre id="evidence-output" tabindex="0" aria-label="Selected execution artifact">Select an artifact.</pre><p>CaseFile captures the command and child exit status; Eval reruns the configured check. SHA-256 detects changes against this local manifest, not host compromise.</p><details><summary>Reproduction artifacts</summary><div class="file-list">'+''.join(f'<a href="checkout-evidence/{h(str(x.relative_to(e)))}">{h(str(x.relative_to(e)))}</a>' for x in files)+'</div></details>')
sec('benchmarks','What this demonstration establishes',paras('The retained command log also contains the same failing test run without CaseFile. Both paths can preserve output and status; CaseFile supplies a structured bundle and context. No reviewer-time improvement was measured. A future comparison must give reviewers equivalent artifacts and randomize order.\n\nSource’s separate 100-contributor benchmark used scripted Node processes making distinct-section edits, not 100 autonomous LLM engineers. It retained a failed attempt and used explicit private-load limits. See the pinned source record for methodology. This is concurrency and history-retention evidence, not general coding productivity.'))
sec('competition','Existing alternatives and Kujo’s proposed fit','<p><a href="https://docs.github.com/en/copilot/concepts/copilot-surfaces/copilot-on-github">GitHub Copilot</a> integrates repository tasks and review. <a href="https://docs.langchain.com/oss/python/langgraph/persistence">LangGraph</a> checkpoints state for recovery and human intervention. CI can execute checks, and observability tooling captures telemetry. Kujo demonstrates local command bundles, explicit evaluation and reviewable exports; a shared service and lower operating effort remain hypotheses. This is a documentation comparison, not hands-on competitive parity testing.</p>')
sec('market','Team subscription scenarios','<p>Proposed $500/team/month ($6,000 annualized). ARR = active paying teams × annual contract. Counts and conversion are unvalidated. The scale ceiling below is a scenario, not a measured addressable market.</p><div class="inputs"><label>Scenario team ceiling<input id="organizations" type="number" min="0" max="1000000" value="1000"></label><label>Annual team price USD<input id="acv" type="number" min="0" max="10000000" value="6000"></label><label>Retained paying teams<input id="customers" type="number" min="0" max="1000000" value="60"></label></div><output id="market-output" aria-live="polite"></output><p>17 teams = $102K ARR; 167 = $1.002M; 1,000 = $6M. Base month-24 case: 60 teams = $360K. Conservative: 25 × $300/month = $90K ARR. Upside: 200 × $500/month = $1.2M ARR. Enterprise 100 × $24K = $2.4M is a separate sensitivity excluded from these cases.</p>')
sec('commercial','What we know and what we are testing',paras('Available now: open local tools, public source and documented host adapters. Planned: a team evidence service at a proposed $500/month; enterprise deployment/support at a separate proposed $24K/year. No paid service, customer revenue or active pilot was verified.\n\nInitial buyer hypothesis: a platform engineering lead reconstructing agent regressions across repositories. Minimum paid scope: intake tied to revisions, retention, search, access controls, review decisions and export/delete. Keep application languages unchanged.\n\nValidation plan: 12 interviews, then 3 qualified design partners and 2 paid pilot conversions over a proposed 90-day program. Ask about actual incidents, reconstruction time, alternatives, budget and purchase process. No interviews or outreach were conducted in this session.\n\nBase assumptions: 1.5% monthly logo churn, 75% gross margin, 1–3 month sales cycle, first revenue around month 6. At $500/month, assumed COGS $125 and gross profit $375; assumed $3,000 CAC implies 8-month payback. Validate with observed cohorts and invoices.'))
sec('funding','Financing discussion inputs','<p>Proposed $6M raise and $30M post-money SAFE cap require founder confirmation. A cap is not a priced valuation. For a priced round, $6M / $30M = 20% simplified ownership before other dilution; SAFE conversion depends on definitive terms.</p><div class="inputs"><label>Raise<select id="raise"><option value="2000000">$2M</option><option value="3000000">$3M</option><option value="6000000" selected>$6M</option></select></label><label>Post-money scenario USD<input id="postmoney" type="number" min="1000000" max="1000000000" value="30000000"></label><label>Months<input id="months" type="number" min="1" max="120" value="24"></label></div><output id="funding-output" aria-live="polite"></output><div id="budget" tabindex="0" role="group" aria-label="Scenario allocation table"></div><button id="export">Export current assumptions JSON</button><p>This proportional sensitivity does not replace the quarterly hiring schedule. Smaller raises require narrower scope. At $6M, simple ownership at $20M/$30M/$40M post-money is 30%/20%/15%. No agreed terms or close date.</p>')
quarter=[sum(v[i] for v in model['quarterlyCosts'].values()) for i in range(8)]
sec('budget','A staged 24-month cash plan','<p>Proposed operating envelope $5.1M plus $900K reserve, no revenue offsets. Average operating spend $212,500/month. Founder compensation remains unresolved: the prior $150K annual cash plus burden differs from the later $375K two-year total. The current sensitivity uses $375K cash with overhead separately budgeted; founder must confirm cash versus fully loaded cost.</p><div class="table-scroll" tabindex="0" role="group" aria-label="Quarterly spending"><table><thead><tr><th>Quarter</th><th>Operating spend USD</th><th>Cash remaining USD</th></tr></thead><tbody>'+''.join(f'<tr><td>Q{i+1}</td><td>{x:,.0f}</td><td>{6000000-sum(quarter[:i+1]):,.0f}</td></tr>' for i,x in enumerate(quarter))+'</tbody></table></div><p>Engineering $1.5M; cloud/models $400K; customer development/distribution $1.34M; founder, product/DX, overhead, legal/security and operations $1.86M. Hiring expands only with activation, paid pilots and retained use. Compensation needs local market and employment-cost quotes. The late commercial envelope is gated spending, not an obligation.</p>')
sec('roadmap','Release spending against evidence',paras('Months 0–6: founder-led discovery, execution reliability and fractional product/DX. Interview 12 buyers and recruit qualified partners. Months 6–12: expand integration and customer engineering only after repeated activation, 3 partners and 2 paid pilots. Months 12–24: expand commercial capacity only after measured retention and support costs.\n\nA $2M–$3M milestone round supports a smaller team and one flagship workflow. $6M supports parallel product, distribution, security and integration work. If buyers cannot identify consequential reconstruction problems or will not pay after evaluation, narrow the product and stop expansion.'))
sec('risks','Risks and open decisions',paras('Demand and pricing are unvalidated. Local evidence is editable; hosted custody and isolation need security work. Incumbents can bundle similar capabilities. Integration contracts vary and language adoption can be slow. Founder concentration, unknown acquisition costs and future financing are material risks.\n\nFounder decisions remain: wedge and package, pricing, instrument and cap, compensation, hiring gates, approved traction and fundraising contact/timing. The existing public contact link is retained for a diligence conversation. Financing terms and commercial packaging remain proposals until agreed.'))
sec('sources','Sources and technical diligence','<p>Research cut: November 11, 2026 (some execution receipts are November 12 UTC). Public-source claims are separated from proposed commercial plans.</p><ul>'+''.join(f'<li><a href="{h(c["source"])}">{h(c["id"])} / {h(c["project"])} pinned source</a></li>' for c in caps)+'''<li><a href="https://github.com/mcp/kujolang/kujolang-mcp">E01: GitHub MCP Registry listing</a></li><li><a href="https://webdevstudios.com/2025/07/03/exciting-webdevstudios-wordpress-news/">F02: WebDevStudios plugin adoption, July 3, 2025</a></li><li><a href="https://robertdevore.com/about/">F01: Founder biography (self-reported)</a></li><li><a href="https://github.com/kujolang/kujo-hermes/tree/bfa94add10a73d5bda6455dda54c36cb56d8f14c/demo/checkout">D01: Original checkout fixture</a></li></ul><p>Full evidence register, model, validation plan and reproduction commands: <a href="diligence.txt">download diligence text</a>.</p><a href="https://robertdevore.com/contact/">Request a technical diligence walkthrough ↗</a>''')
nav=''.join(f'<a href="#{id}">{h(title)}</a>' for id,title,_ in sections)
(p/'assets/appendix.html').write_text('<!doctype html><html lang="en"><head><meta charset="utf-8"><link rel="icon" href="kujo-logomark.svg"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Kujo investor diligence — evidence, strategy and scenarios</title><meta name="description" content="Inspect Kujo technical evidence, the checkout regression demonstration, proposed team service, financing scenarios and validation plan."><link rel="canonical" href="https://invest.kujolang.ai/assets/deck/appendix"><link rel="stylesheet" href="appendix.css"></head><body><a class="skip" href="#main">Skip to diligence content</a><header><a href="../../1/">← Presentation</a><p>KUJO / INVESTOR DILIGENCE</p><h1>The evidence behind the argument.</h1><nav aria-label="Appendix sections">'+nav+'</nav></header><main id="main">'+''.join(x[2] for x in sections)+'</main><footer>Kujo · Proposed plans are not commitments.</footer><script src="appendix.js" defer></script></body></html>')
